1	//! Windows filesystem module for CipherBox Desktop.
2	//!
3	//! Provides WinFsp-based mount and unmount functions.
4	//! WinFsp operation implementations (FileSystemContext, read/write/dir ops)
5	//! live in the cipherbox-fuse crate at `cipherbox_fuse::platform::windows`.
6	
7	#[cfg(feature = "winfsp")]
8	mod mount_impl {
9	    use std::collections::HashMap;
10	    use std::sync::atomic::AtomicU64;
11	    use std::sync::{Arc, Mutex};
12	
13	    use zeroize::Zeroizing;
14	
15	    use crate::fuse::{
16	        cache, inode, CipherBoxFS, PendingContent, PendingFilePointer, PendingRefresh,
17	        PublishCoordinator, UploadComplete,
18	    };
19	    use crate::state::AppState;
20	
21	    /// Global handle to the WinFsp stop signal for clean shutdown.
22	    /// Replaced on each mount so remount after unmount works correctly.
23	    static WINFSP_STOP: Mutex<Option<Arc<std::sync::atomic::AtomicBool>>> = Mutex::new(None);
24	
25	    /// Mount the WinFsp filesystem after successful authentication.
26	    ///
27	    /// Creates the CipherBoxFS with keys from AppState, pre-populates the root
28	    /// folder from IPNS, and spawns the WinFsp event loop on a dedicated thread.
29	    ///
30	    /// Returns a JoinHandle for the mount thread.
31	    ///
32	    /// Key differences from macOS mount:
33	    /// - WinFsp creates the mount directory as a reparse point -- do NOT pre-create it
34	    /// - No Spotlight suppression (Windows-specific)
35	    /// - Uses WinFsp FileSystemHost instead of fuser::mount2
36	    pub async fn mount_filesystem(
37	        state: &AppState,
38	        rt: tokio::runtime::Handle,
39	        private_key: Vec<u8>,
40	        public_key: Vec<u8>,
41	        root_folder_key: Vec<u8>,
42	        root_ipns_name: String,
43	        root_ipns_private_key: Option<Vec<u8>>,
44	        tee_public_key: Option<Vec<u8>>,
45	        tee_key_epoch: Option<u32>,
46	        max_versions_per_file: usize,
47	        version_cooldown_ms: u64,
48	    ) -> Result<std::thread::JoinHandle<()>, String> {
49	        let mount_path = crate::fuse::mount_point();
50	
51	        // WinFsp creates the mount directory as a reparse point.
52	        // If a stale mount directory exists from a crash, clean it.
53	        if mount_path.exists() {
54	            match std::fs::remove_dir_all(&mount_path) {
55	                Ok(()) => log::info!("Cleaned stale mount point: {}", mount_path.display()),
56	                Err(e) => log::warn!("Failed to clean stale mount point {}: {}", mount_path.display(), e),
57	            }
58	        }
